import java.io.*;
import java.util.*;

public class ll {
    public static void main(String[] args) throws IOException {
        new gg();
    }
}

class gg {
    gg() throws IOException {
        FScanner fs = new FScanner(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        int n = fs.nextInt();
        char[] word = fs.nextLine().toCharArray();
        int[] vals = fs.iarr(n);
        int[] badones = new int[26];
        int m = 0;
        for (int i = 0; i < n / 2; i++) {
            if (word[i] == word[n - i - 1]) {
                badones[word[i] - 'a']++;
                m++;
            }
        }
        int val = -1;
        for (int i = 0; i < 26; i++) {
            if (badones[i] * 2 > m) {
                val = i;
                break;
            }
        }
        long sum = 0;
        if (val == -1) {
            for (int i = 0; i < n / 2; i++) {
                if (word[i] != word[n - i - 1])
                    sum += vals[i] + vals[n - i - 1];
                else
                    sum += Math.max(vals[i], vals[n - i - 1]);
            }
        } else {
            int others = badones[val] - (m - badones[val]);
            ArrayList<Integer> appr = new ArrayList<>();
            for (int i = 0; i < n / 2; i++) {
                if (word[i] != word[n - i - 1] && word[i] != 'a' + val && word[n - i - 1] != 'a' + val)
                    appr.add(Math.min(vals[i], vals[n - i - 1]));
            }
            Collections.sort(appr);
            for (int i = 0; i < n / 2; i++) {
                if (word[i] == word[n - i - 1])
                    sum += Math.max(vals[i], vals[n - i - 1]);
                else
                    sum += vals[i] + vals[n - i - 1];
            }
            for (int i = 0; i < others; i++)
                sum -= appr.get(i);
        }
        pw.println(sum);
        pw.close();
    }
}

class FScanner {
    StringTokenizer st;
    BufferedReader reader;
    FScanner(InputStreamReader isr) throws IOException {
        reader = new BufferedReader(isr);
    }
    String nextLine() throws IOException {
        return reader.readLine();
    }
    String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String s = reader.readLine();
            if (s == null) return null;
            st = new StringTokenizer(s);
        }
        return st.nextToken();
    }
    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }
    int[] iarr(int n) throws IOException {
        int[] mas = new int[n];
        for (int i = 0; i < n; i++) mas[i] = nextInt();
        return mas;
    }
}
